-- V30: Bot/automated chat fields + add Rockzzz contestant to BB Tamil S10

-- ── Bot fields on chat_messages ───────────────────────────────────────────────
-- automated: true when generated by ScheduledFanChatJob; false for all human messages
-- bot_type:  e.g. 'FAN_COMMENT_BOT', null for human messages
-- Columns are nullable so all existing rows default to human (automated = false).

ALTER TABLE chat_messages
    ADD COLUMN IF NOT EXISTS automated BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS bot_type  VARCHAR(50);

CREATE INDEX IF NOT EXISTS idx_chat_messages_automated
    ON chat_messages(room_id, automated, created_at DESC)
    WHERE automated = TRUE;

-- ── Add Rockzzz to Bigg Boss Tamil Season 10 ─────────────────────────────────
-- Idempotent: only inserts if the slug does not already exist in this season.

INSERT INTO contestants (season_id, name, slug, profile_image, bio, status, created_at, updated_at)
SELECT
    s.id,
    'Rockzzz',
    'rockzzz',
    'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=400',
    'Wildcard entrant',
    'active',
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM seasons s
WHERE s.show_id  = (SELECT id FROM shows WHERE slug = 'bigg-boss-tamil')
  AND s.season_number = 10
  AND NOT EXISTS (
      SELECT 1 FROM contestants c2
      WHERE c2.season_id = s.id AND c2.slug = 'rockzzz'
  );
